    lo = _mm256_and_si256(lo, _mm256_set1_epi32(65535));
    hi = _mm256_and_si256(hi, _mm256_set1_epi32(65535));
    return _mm256_permute4x64_epi64(_mm256_packus_epi32(lo, hi), 0xd8);
